import json,collections,sys,datetime
def load(f): return [json.loads(l) for l in open('/app/export/'+f+'.ndjson')]
types=['Patient','EpisodeOfCare','Condition','Observation','Specimen','Basic','MedicationAdministration','MedicationDispense','DocumentReference','AllergyIntolerance','Task']
R={t:load(t) for t in types}
byid={r['id']:r for t in types for r in R[t]}
def ext(r,u):
    for e in r.get('extension',[]):
        if e['url'].endswith('/'+u):
            for k,v in e.items():
                if k.startswith('value'): return v
    return None
def et(r): return ext(r,'event-time') or r.get('period',{}).get('start','')
def subj(r):
    for k in ('subject','patient','for'):
        if k in r and isinstance(r[k],dict) and 'reference' in r[k]: return r[k]['reference'].split('/')[-1]
    return None
pats={p['id']:p for p in R['Patient']}
spec_by_id={s['id']:s for s in R['Specimen']}
acc_basic=collections.defaultdict(list)
for b in R['Basic']: acc_basic[ext(b,'accession')].append(b)

def render(pid):
    out=[]
    p=pats[pid]
    out.append(f"PATIENT {pid} {p['name'][0]['text']} MRN={p['identifier'][0]['value']} DOB={p['birthDate']} {p['gender']}")
    for e in R['EpisodeOfCare']:
        if subj(e)==pid: out.append(f"  EPISODE {e['id']} start={e['period']['start']} {e['type'][0]['text']}")
    ev=[]
    for t in types:
        if t in ('Patient','EpisodeOfCare'): continue
        for r in R[t]:
            if subj(r)==pid: ev.append(r)
    ev.sort(key=lambda r: str(et(r)))
    for r in ev:
        t=r['resourceType']; i=r['id']; tm=str(et(r))[:16]
        if t=='Condition':
            out.append(f"  {tm} Condition {i}: {r['code']['text']} rec={r.get('recorder',{}).get('display')}")
        elif t=='Observation':
            sp=r.get('specimen',{}).get('reference','').split('/')[-1]
            acc=r.get('identifier',[{}])[0].get('value')
            notes='; '.join(n['text'] for n in r.get('note',[]))
            out.append(f"  {tm} Obs {i}: {r['code']['text']} = {r.get('valueString')} [{r['status']}] coll={r.get('effectiveDateTime','')[:16]} issued={r.get('issued','')[:16]} acc={acc} spec={sp}"+(f" NOTE: {notes}" if notes else ""))
            if sp and sp in spec_by_id:
                s=spec_by_id[sp]
                out.append(f"        Specimen {sp}: acc={s.get('accessionIdentifier',{}).get('value')} coll={s.get('collection',{}).get('collectedDateTime','')[:16]} by={s.get('collection',{}).get('collector',{}).get('display')} label={ext(s,'label-name')}/{ext(s,'label-mrn')}/{ext(s,'label-dob')} subj={subj(s)}")
            for b in acc_basic.get(acc,[]):
                out.append(f"        Accession {b['id']}: acc={ext(b,'accession')} name={ext(b,'patient-name')} mrn={ext(b,'patient-mrn')} dob={ext(b,'patient-dob')} recv={str(ext(b,'received'))[:16]} by={b.get('author',{}).get('display')}")
        elif t=='MedicationAdministration':
            notes='; '.join(n['text'] for n in r.get('note',[]))
            out.append(f"  {tm} MedAdmin {i}: {r.get('medicationCodeableConcept',{}).get('text')} {r['dosage']['text']} [{r['status']}] perf={r.get('performer',[{}])[0].get('actor',{}).get('display')}"+(f" NOTE: {notes}" if notes else ""))
        elif t=='MedicationDispense':
            notes='; '.join(n['text'] for n in r.get('note',[]))
            out.append(f"  {tm} MedDisp {i}: {r.get('medicationCodeableConcept',{}).get('text')} qty={r.get('quantity',{}).get('value')} days={r.get('daysSupply',{}).get('value')} inst={r.get('dosageInstruction',[{}])[0].get('text')} NOTE:{notes}")
        elif t=='DocumentReference':
            out.append(f"  {tm} Doc {i} [{r['type']['text']}] by {r.get('author',[{}])[0].get('display')} ({ext(r,'author-role')}):\n        "+r['description'].replace('\n','\n        '))
        elif t=='AllergyIntolerance':
            out.append(f"  {tm} Allergy {i}: {r['code']['text']} {[m['text'] for rx in r.get('reaction',[]) for m in rx['manifestation']]}")
        elif t=='Task':
            if r['status']=='requested':
                out.append(f"  {tm} REQUEST {i}: {r['code']['coding'][0]['code']} focus={r.get('focus',{}).get('reference')} :: {r.get('description')}")
            else:
                out.append(f"  {tm} ITEM {i}: {r.get('businessStatus')}")
    return '\n'.join(out)
if __name__=='__main__':
    for pid in sys.argv[1:]: print(render(pid)); print('-'*80)
